&lt;hr&gt;
&lt;h4 style=&quot;line-height: 1.1;&quot; data-section-id=&quot;l5aaog&quot; data-start=&quot;1455&quot; data-end=&quot;1475&quot;&gt;&lt;span style=&quot;color: rgb(239, 48, 141);&quot;&gt;&lt;sup&gt;Equal Opportunity&lt;/sup&gt;&lt;/span&gt;&lt;/h4&gt;
